def choose_move(observation):
    def clamp_step(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def pos(v, default=(0, 0)):
        try:
            if isinstance(v, (list, tuple)) and len(v) >= 2:
                return v[0], v[1]
        except Exception:
            pass
        return default

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(a, b):
        return [clamp_step(b[0] - a[0]), clamp_step(b[1] - a[1])]

    def step_away(a, b):
        return [clamp_step(a[0] - b[0]), clamp_step(a[1] - b[1])]

    env = observation.get("environment_name", "") or ""
    sx, sy = pos(observation.get("self_position"), (0, 0))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    w = observation.get("grid_width", 0) or 0
    h = observation.get("grid_height", 0) or 0
    self_role = observation.get("self_role", "")

    if env == "pursuit_evasion":
        if self_role == "pursuer":
            return step_toward((sx, sy), (ox, oy))
        corners = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
        if w > 0 and h > 0:
            target = max(corners, key=lambda c: dist(c, (ox, oy)))
            return step_toward((sx, sy), target)
        return step_away((sx, sy), (ox, oy))

    if env == "territory_control":
        targets = observation.get("unclaimed_cells")
        if not targets:
            targets = observation.get("opponent_territory")
        if not targets:
            targets = observation.get("frontier_cells")
        if targets:
            best = None
            best_score = None
            for item in targets:
                t = pos(item, None)
                if t is None:
                    continue
                score = dist((sx, sy), t)
                if best is None or score < best_score or (score == best_score and (t[0], t[1]) < best):
                    best = t
                    best_score = score
            if best is not None:
                return step_toward((sx, sy), best)
        return step_away((sx, sy), (ox, oy))

    resources = observation.get("resources") or observation.get("resource_positions") or []
    if resources:
        best = None
        best_score = None
        for item in resources:
            t = pos(item, None)
            if t is None:
                continue
            score = dist((sx, sy), t)
            if best is None or score < best_score or (score == best_score and (t[0], t[1]) < best):
                best = t
                best_score = score
        if best is not None:
            return step_toward((sx, sy), best)

    opps = observation.get("opponents") or observation.get("enemy_positions") or []
    if opps:
        nearest = None
        nearest_score = None
        for item in opps:
            t = pos(item, None)
            if t is None:
                continue
            score = dist((sx, sy), t)
            if nearest is None or score < nearest_score:
                nearest = t
                nearest_score = score
        if nearest is not None:
            return step_away((sx, sy), nearest)

    if ox != sx or oy != sy:
        return step_toward((sx, sy), (ox, oy))
    return [0, 0]

